#include <linux/uaccess.h>
#include <linux/bitmap.h>

int compat_sys_mbind(int mode, compat_ulong_t __user *nmask, compat_ulong_t maxnode) {
    int err;
    unsigned long *bitmap = NULL;
    unsigned long nbits = maxnode;
    unsigned long size;

    if (!nmask || maxnode == 0)
        return -EINVAL;

    size = (nbits + 7) / 8; // Calculate size in bytes
    bitmap = kmalloc(size, GFP_KERNEL);
    if (!bitmap)
        return -ENOMEM;

    if (copy_from_user(bitmap, nmask, size)) {
        err = -EFAULT;
        goto out;
    }

    err = sys_mbind(mode, bitmap, nbits);

    if (copy_to_user(nmask, bitmap, size))
        err = -EFAULT;

out:
    kfree(bitmap);
    return err;
}

int compat_sys_mbind(int mode, compat_ulong_t __user *nmask, compat_ulong_t maxnode) {
    int err = 0;
    unsigned long *bitmap = NULL;
    int nbits = maxnode;
    int numentries = BITS_TO_LONGS(nbits);

    if (nmask) {
        bitmap = compat_alloc_user_space(numentries * sizeof(unsigned long));
        if (!access_ok(VERIFY_READ, nmask, numentries * sizeof(compat_ulong_t))) {
            return -EFAULT;
        }

        {
            int i;
            compat_ulong_t val;
            for (i = 0; i < numentries; i++) {
                if (__get_user(val, &nmask[i])) {
                    err = -EFAULT;
                    goto out;
                }
                if (i < numentries - 1) {
                    bitmap[i] = (unsigned long)val;
                } else {
                    bitmap[i] = (unsigned long)val;
                }
            }
        }

        if (__put_user((compat_ulong_t)bitmap, &nmask)) {
            err = -EFAULT;
            goto out;
        }
    }

    err = sys_mbind(mode, nmask, nbits);

out:
    if (bitmap && nmask)
        compat_free_user_space(bitmap);
    return err;
}

#include <linux/mm.h>
