SYSCALL_DEFINE3(set_mempolicy_compat, int, mode, compat_ulong_t __user *, nmask,
                compat_ulong_t, maxnode)
{
    int err = 0;
    unsigned long *bmp = NULL;
    unsigned int nbits, maxpages;

    if (maxnode == 0)
        return -EINVAL;

    nbits = maxnode;
    maxpages = (nbits + BITS_PER_LONG - 1) / BITS_PER_LONG;

    if (nmask) {
        bmp = compat_alloc_user_space(maxpages * sizeof(unsigned long));
        if (copy_from_user(bmp, nmask, maxpages * sizeof(compat_ulong_t)))
            return -EFAULT;
        err = do_set_mempolicy(mode, bmp, nbits);
        if (!err && copy_to_user(nmask, bmp, maxpages * sizeof(compat_ulong_t)))
            err = -EFAULT;
    } else {
        err = do_set_mempolicy(mode, NULL, 0);
    }

    return err;
}

int compat_sys_mempolicy(int mode, compat_ulong_t __user *nmask, compat_ulong_t maxnode)
{
    int err;
    unsigned long *bmp = NULL;
    unsigned long bits;
    unsigned long sz;
    compat_ulong_t maxnode_val = maxnode;

    if (!maxnode_val)
        return -EINVAL;

    bits = maxnode_val;
    sz = (bits + BITS_PER_LONG - 1) / (8 * sizeof(compat_ulong_t)) * sizeof(compat_ulong_t);

    if (nmask) {
        bmp = compat_alloc_user_space(sz);
        if (copy_from_user(bmp, nmask, sz))
            return -EFAULT;
    }

    err = sys_mempolicy(mode, bmp, bits);

    if (nmask && copy_to_user(nmask, bmp, sz))
        err = -EFAULT;

    return err;
}

