int sys_mempolicy_set_compat(int mode, compat_ulong_t __user *nmask, compat_ulong_t maxnode) {
    unsigned long *bmp = NULL;
    int err = 0;
    int nbits = 0;
    int size = 0;

    if (maxnode > 0) {
        nbits = maxnode;
        size = ((nbits + 7) / 8) * 8;
        bmp = kmalloc(size, GFP_KERNEL);
        if (!bmp) {
            return -ENOMEM;
        }

        if (copy_from_user(bmp, nmask, size)) {
            err = -EFAULT;
            goto out;
        }

        if (copy_to_user(nmask, bmp, size)) {
            err = -EFAULT;
            goto out;
        }
    }

    err = sys_mempolicy(mode, bmp, nbits);

out:
    kfree(bmp);
    return err;
}
